(()=>{let projects=[],active=0,rotation=0;const ring=document.querySelector('#repo-ring'),index=document.querySelector('#repo-index'),detail=document.querySelector('#repo-detail'),dialog=document.querySelector('#repo-dialog');function el(tag,text,cls){const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n}function link(text,url,cls){const a=el('a',text,cls);a.href=url;a.target='_blank';a.rel='noopener';return a}function choose(i,direction){if(!projects.length)return;if(direction)rotation+=direction*90;else{rotation+=(i-active)*90}active=(i+projects.length)%projects.length;ring.style.transform=`rotateY(${-rotation}deg)`;ring.querySelectorAll('.repo-card').forEach((c,j)=>{c.inert=j!==active;c.setAttribute('aria-hidden',String(j!==active))});[...index.children].forEach((b,j)=>b.setAttribute('aria-pressed',String(j===active)))}
const flows={support:[['Ticket','Start with the problem','A visitor submits a support ticket description to the triage API.'],['Classify','A focused model call','The LLM extracts category, severity and a summary. This portfolio does not send ticket data to that repository.'],['Retrieve','Find related knowledge','The repository searches a small knowledge base using TF-IDF similarity and distinguishes known from new issues.'],['Resolve','Suggest a next action','The response includes matching knowledge-base entries and suggested next steps. This is an explainer, not a connected support service.']],memory:[['Code','Version the project context','Code, notes, context and handoffs live with the project in GitHub.'],['Folder','A shared memory space','A structured synced folder carries inbox items, daily context and project pointers across human and AI tools.'],['Handoff','Keep the next conversation grounded','The protocol supplies context and handoff templates. This is a documented protocol, not an automatically connected integration.']],news:[['Extract','Article text','The browser extension collects article text from the active page and passes it to the prediction endpoint.'],['Vectorize','Turn words into features','The documented baseline uses a TF-IDF vectorizer to create numeric features from the text.'],['Predict','The trained classifier','The FastAPI backend loads a trained scikit-learn model. No classifier is hosted in this portfolio, so this preview does not judge real articles.'],['Explain','Return the result','The extension displays the returned label and confidence. Open the repository for the backend, extension and training scripts.']],checks:[['Input','Start with a check','The ACPS repository contains an automatic check processing application.'],['Process','A modular build','Processors and supporting utilities organise the application logic. This explainer does not upload documents or run its processing code.'],['Present','Bring the result forward','Templates provide the presentation layer. Review the source to explore its actual behavior and requirements.']],food:[['Browse','Explore the menu','Feastwala is an open-source food subscription portal. Its README describes browsing available food options.'],['Choose','Find an everyday fit','The product concept connects food discovery and subscriptions for busy professionals.'],['Order','From menu to meal','The repository describes online ordering and a responsive experience. This portfolio is an explainer and does not place orders.']]};
const movies=[{title:'Interstellar',v:[1,1,0,.9]},{title:'Arrival',v:[1,.2,0,1]},{title:'The Martian',v:[1,.7,.3,.7]},{title:'Inception',v:[.8,1,0,.8]},{title:'The Grand Budapest Hotel',v:[0,.2,1,.4]},{title:'Moonrise Kingdom',v:[0,.1,1,.5]}];const similarity=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0)/(Math.hypot(...a)*Math.hypot(...b));function openDemo(p){detail.replaceChildren(el('p',p.name+' / PUBLIC REPOSITORY','eyebrow'),el('h2',p.title),el('p',p.description),el('p',p.demoLabel+(p.video?' · from the project repository':' · illustrative preview, separate from repository runtime'),'eyebrow'));if(p.video){const video=el('video');video.controls=true;video.playsInline=true;video.preload='metadata';video.src=p.video;if(p.poster)video.poster=p.poster;detail.append(video,el('p',p.videoNote||'Repository recording.'))}else if(p.demo==='movies'){const label=el('label','Pick a film to explore similarity.');label.htmlFor='movie-select';const select=el('select');select.id='movie-select';movies.forEach((m,i)=>{const o=el('option',m.title);o.value=i;select.append(o)});const result=el('div',null,'demo-stage');result.setAttribute('aria-live','polite');function recommend(){const selected=movies[Number(select.value)];const ranked=movies.filter(m=>m!==selected).map(m=>({...m,score:similarity(m.v,selected.v)})).sort((a,b)=>b.score-a.score).slice(0,3);result.replaceChildren(el('h4','Find your next watch'));const list=el('div',null,'movie-results');ranked.forEach(m=>{const row=el('span',m.title);row.append(el('small',Math.round(m.score*100)+'% similarity'));list.append(row)});result.append(list,el('p','Small hand-authored sample vectors demonstrate cosine similarity. These are not results from the repository’s trained model or TMDB dataset.'))}select.addEventListener('change',recommend);recommend();detail.append(label,select,result)}else{const stages=flows[p.demo]||flows.news;const tabs=el('div',null,'demo-tabs');tabs.setAttribute('aria-label','Explore the pipeline');const stage=el('div',null,'demo-stage');stage.setAttribute('aria-live','polite');stages.forEach((s,i)=>{const b=el('button',String(i+1).padStart(2,'0')+' / '+s[0]);b.addEventListener('click',()=>{[...tabs.children].forEach(n=>n.setAttribute('aria-pressed',String(n===b)));stage.replaceChildren(el('h4',s[1]),el('p',s[2]))});tabs.append(b);if(!i)b.click()});detail.append(tabs,stage)}detail.append(link('Explore the real repository',p.url,'source-link'));dialog.showModal()}dialog.addEventListener('close',()=>dialog.querySelectorAll('video').forEach(v=>v.pause()));
fetch('projects.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{projects=data;projects.forEach((p,i)=>{const card=el('article',null,'repo-card');if(p.preview){const thumb=el('img');thumb.src=p.preview;thumb.alt='ICR Studios interface using fictional sample forms';thumb.loading='lazy';card.append(thumb)}card.style.transform=`rotateY(${i*90}deg) translateZ(285px)`;card.append(el('p',p.language+' / '+String(i+1).padStart(2,'0'),'eyebrow'),el('h3',p.title),el('p',p.description));const links=el('div',null,'repo-links');const demo=el('button','Explore concept');demo.addEventListener('click',()=>openDemo(p));links.append(demo,link('View code',p.url));card.append(links);ring.append(card);const b=el('button',p.name);b.setAttribute('aria-pressed',String(i===0));b.addEventListener('click',()=>choose(i));index.append(b)});choose(0);document.querySelector('#repos-prev').addEventListener('click',()=>choose(active-1,-1));document.querySelector('#repos-next').addEventListener('click',()=>choose(active+1,1));let last=-1;const section=document.querySelector('#repositories');function scroll(){if(document.body.classList.contains('motion-off')||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const r=section.getBoundingClientRect();if(r.top>innerHeight||r.bottom<0)return;const p=Math.max(0,Math.min(.999,(innerHeight-r.top)/(innerHeight+r.height)));const n=Math.min(projects.length-1,Math.floor(p*projects.length));if(n!==last){last=n;choose(n)}}window.addEventListener('scroll',scroll,{passive:true});return siteSettings.then(s=>s.backend?fetch(new URL('api/repos',document.baseURI)):Promise.reject()).then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>({...data,live:true})).catch(()=>fetch('repos-snapshot.json').then(r=>{if(!r.ok)throw Error();return r.json()}))}).then(data=>{document.querySelector('#repo-status').textContent=data.live?'Public GitHub repositories synced':'Public repository snapshot · '+data.capturedAt;const extra=data.repos.filter(r=>!projects.some(p=>p.name.toLowerCase()===r.name.toLowerCase()));extra.forEach(r=>{const a=link(r.name,r.url);if(r.description)a.title=r.description;document.querySelector('#more-repos').append(a)})}).catch(()=>{document.querySelector('#repo-status').textContent='Curated projects · live GitHub sync unavailable'})})();
